create extension if not exists "pgcrypto";
create type public.member_role as enum ('owner','manager','staff');
create type public.record_status as enum ('draft','scheduled','sent','completed','active','inactive');

create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, settings jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.locations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, business_type text, address text, city text default 'Cusco', phone text, timezone text default 'America/Lima', active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text, phone text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.organization_members (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, profile_id uuid not null references public.profiles on delete cascade, role public.member_role not null default 'staff', location_ids uuid[] default '{}', created_at timestamptz default now(), updated_at timestamptz default now(), unique(organization_id,profile_id));
create table public.customers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, first_name text not null, last_name text, country_code text not null, phone text not null, phone_verified boolean default false, email text, nationality text, country_of_residence text, date_of_birth date, preferred_language text default 'es', gender text, city text, system_notes text[], marketing_consent boolean default false, marketing_consent_at timestamptz, registration_source text, first_visit_at timestamptz, latest_visit_at timestamptz, total_visits integer default 0, total_spend numeric(12,2) default 0, current_points integer default 0, lifetime_points integer default 0, loyalty_tier text default 'Explorador', referral_code text unique default upper(substr(encode(gen_random_bytes(6),'hex'),1,6)), referred_by uuid references public.customers, referral_count integer default 0, created_at timestamptz default now(), updated_at timestamptz default now(), unique(organization_id,country_code,phone));
create table public.loyalty_tiers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, points_threshold integer default 0, visits_threshold integer default 0, icon text, benefits jsonb default '[]', sort_order integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.loyalty_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, event_type text not null, points integer default 0, multiplier numeric(6,2), conditions jsonb default '{}', enabled boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.customer_visits (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, location_id uuid not null references public.locations, customer_id uuid not null references public.customers, purchase_amount numeric(12,2) default 0, registered_by uuid references public.profiles, visited_at timestamptz default now(), created_at timestamptz default now(), updated_at timestamptz default now());
create table public.transactions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, location_id uuid references public.locations, customer_id uuid references public.customers, visit_id uuid references public.customer_visits, type text not null, amount numeric(12,2) default 0, metadata jsonb default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.point_transactions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, customer_id uuid not null references public.customers, visit_id uuid references public.customer_visits, amount integer not null, reason text not null, balance_after integer, expires_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.rewards (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, location_id uuid references public.locations, name text not null, description text, image_url text, reward_type text not null, points_required integer not null, valid_from timestamptz, valid_until timestamptz, inventory integer, tier_requirement text, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.reward_redemptions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, reward_id uuid not null references public.rewards, customer_id uuid not null references public.customers, location_id uuid references public.locations, code text not null, status text default 'pending', points_spent integer not null, redeemed_at timestamptz, validated_by uuid references public.profiles, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.campaigns (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, channel text not null, audience jsonb default '{}', message text, promotion jsonb, scheduled_at timestamptz, status public.record_status default 'draft', metrics jsonb default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.automations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, trigger_config jsonb not null, condition_config jsonb default '{}', action_config jsonb not null, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.referrals (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, referrer_customer_id uuid not null references public.customers, referred_customer_id uuid references public.customers, code text not null, status text default 'registered', qualifying_transaction_id uuid references public.transactions, converted_at timestamptz, attributed_revenue numeric(12,2) default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.partners (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, partner_organization_id uuid references public.organizations, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.partner_offers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, partner_id uuid references public.partners, referring_location_id uuid references public.locations, receiving_location_id uuid references public.locations, name text not null, qualification jsonb default '{}', benefit jsonb default '{}', metrics jsonb default '{}', active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.qr_codes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, location_id uuid references public.locations, campaign_id uuid references public.campaigns, source_type text not null, source_id text not null, name text not null, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now(), unique(organization_id,source_id));
create table public.demo_requests (id uuid primary key default gen_random_uuid(), first_name text not null, last_name text, business_name text not null, business_type text, city text, location_count integer, monthly_customers integer, email text, whatsapp text, preferred_contact text, message text, created_at timestamptz default now(), updated_at timestamptz default now());

create or replace function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from organization_members where organization_id=target_org and profile_id=auth.uid()) $$;
create or replace function public.is_org_admin(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from organization_members where organization_id=target_org and profile_id=auth.uid() and role in ('owner','manager')) $$;

alter table public.organizations enable row level security;
alter table public.locations enable row level security; alter table public.organization_members enable row level security; alter table public.customers enable row level security;
alter table public.customer_visits enable row level security; alter table public.transactions enable row level security; alter table public.point_transactions enable row level security;
alter table public.loyalty_tiers enable row level security; alter table public.loyalty_rules enable row level security; alter table public.rewards enable row level security; alter table public.reward_redemptions enable row level security;
alter table public.campaigns enable row level security; alter table public.automations enable row level security; alter table public.referrals enable row level security; alter table public.partners enable row level security; alter table public.partner_offers enable row level security; alter table public.qr_codes enable row level security; alter table public.demo_requests enable row level security;

create policy "members read organizations" on public.organizations for select using (is_org_member(id));
create policy "public submits demos" on public.demo_requests for insert to anon,authenticated with check (true);
do $$ declare t text; begin foreach t in array array['locations','organization_members','customers','customer_visits','transactions','point_transactions','loyalty_tiers','loyalty_rules','rewards','reward_redemptions','campaigns','automations','referrals','partners','partner_offers','qr_codes'] loop execute format('create policy "tenant read %1$s" on public.%1$I for select using (public.is_org_member(organization_id))',t); execute format('create policy "tenant create %1$s" on public.%1$I for insert with check (public.is_org_member(organization_id))',t); execute format('create policy "admin update %1$s" on public.%1$I for update using (public.is_org_admin(organization_id))',t); execute format('create policy "admin delete %1$s" on public.%1$I for delete using (public.is_org_admin(organization_id))',t); end loop; end $$;

create index customers_org_phone_idx on public.customers(organization_id,phone);
create index visits_org_date_idx on public.customer_visits(organization_id,visited_at desc);
create index transactions_org_date_idx on public.transactions(organization_id,created_at desc);
create index referrals_org_status_idx on public.referrals(organization_id,status);
